package com.bank.route;

import java.util.logging.*;

public class RouteDemo {
    private static final Logger log = Logger.getLogger("Route");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        RouteTable rt = new RouteTable();
        rt.add(new Route("10.0.0.0/16", "local"));
        rt.add(new Route("172.16.0.0/16", "pcx-0peer123"));  // peered analytics VPC
        rt.add(new Route("0.0.0.0/0", "nat-0gateway"));       // outbound internet

        PacketRouter router = new PacketRouter(rt);
        log.info(() -> "To 10.0.5.9 (internal):  " + router.route("10.0.5.9"));
        log.info(() -> "To 172.16.5.9 (peer):    " + router.route("172.16.5.9"));
        log.info(() -> "To 52.1.2.3 (internet):  " + router.route("52.1.2.3"));
    }
}

